PRESERVED_TITLES = {'Conda & Conda-Build', 'VSCode (python)', 'Planet Scipy', 'Numfocus', 'Conda-Forge'}
CJK = re.compile(r'[\u3400-\u9fff]')


def native_card(row, listing):
    from anaconda_navigator.widgets.lists.content import ListItemContent
    item = ListItemContent(title=row['title'], uri=row['uri'], summary=row.get('summary', ''),
                           tags=row.get('tags', []), button=row.get('button', ''),
                           banner=row.get('banner', ''), path='')
    listing.addItem(item)
    return item


def render_representative_cards(destination):
    """Export actual source-native card widgets; no network or install API calls."""
    from anaconda_navigator.widgets.lists.content import ListWidgetContent
    app = QtWidgets.QApplication.instance()
    if app is None:
        raise RuntimeError('Create the QApplication and apply engine inside the isolated verifier first')
    destination = Path(destination)
    destination.mkdir(parents=True, exist_ok=True)
    from anaconda_navigator.utils.styles import load_style_sheet
    previous_style = app.styleSheet()
    app.setStyleSheet(load_style_sheet())
    selected = {}
    for row in CARD_SNAPSHOT:
        kind = nav_assets.badge_kind(row.get('banner', ''))
        if kind:
            selected.setdefault(kind, row)
        elif row['source'] == 'cached':
            for tag in ('documentation', 'forum', 'social'):
                if tag in row.get('tags', []):
                    selected.setdefault(tag, row)
    paths = []
    references = []
    for kind, row in selected.items():
        listing = ListWidgetContent()
        item = native_card(row, listing)
        widget = item.widget
        widget.resize(widget.minimumSize())
        widget.show()
        app.processEvents()
        item.update_thumbnail()
        app.processEvents()
        path = destination / ('native-card-' + kind + '.png')
        if not widget.grab().save(str(path)):
            raise AssertionError('Native card PNG save failed: ' + str(path))
        widget.close()
        references.append((listing, item))
        paths.append(path)
    app.setStyleSheet(previous_style)
    return paths


class PageCoverageTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.app = QtWidgets.QApplication.instance() or QtWidgets.QApplication([])

    def setUp(self):
        engine.uninstall()
        engine.apply()

    def tearDown(self):
        engine.uninstall()

    def test_all_pinned_content_titles_summaries_buttons_and_raw_fields(self):
        from anaconda_navigator.widgets.lists.content import ListWidgetContent
        self.assertEqual(len(CARD_SNAPSHOT), 150)
        self.assertEqual(sum(row['source'] == 'cached' for row in CARD_SNAPSHOT), 99)
        self.assertEqual(sum(row['source'] == 'bundled' for row in CARD_SNAPSHOT), 51)
        self.assertEqual(len({row['title'] for row in CARD_SNAPSHOT}), 104)
        listing = ListWidgetContent()
        fallback = {'documentation': '阅读', 'webinar': '探索', 'event': '了解更多',
                    'video': '查看', 'training': '探索', 'forum': '探索', 'social': '参与'}
        for row in CARD_SNAPSHOT:
            with self.subTest(source=row['source'], title=row['title']):
                item = native_card(row, listing)
                self.assertEqual(item.title, row['title'])
                self.assertEqual(item.uri, row['uri'])
                self.assertEqual(item.summary, row.get('summary', ''))
                self.assertEqual(item.tags, row.get('tags', []))
                self.assertEqual(item.button, row.get('button', ''))
                shown = item.label_text.text()
                if row['title'] in PRESERVED_TITLES:
                    self.assertEqual(shown, row['title'])
                else:
                    self.assertRegex(shown, CJK)
                    self.assertNotEqual(shown, row['title'])
                original_hover = item.frame_hover.summary
                item.frame_hover.text_document.setHtml(original_hover)
                hover = item.frame_hover.text_document.toPlainText()
                self.assertEqual(item.frame_hover.summary, original_hover)
                if row.get('summary'):
                    self.assertNotIn(html.unescape(row['summary']), hover)
                    self.assertRegex(hover, CJK)
                if row.get('button'):
                    self.assertRegex(item.button_text.text(), CJK)
                else:
                    self.assertEqual(item.button_text.text(), fallback.get(item.tag, ''))
        print('PAGE_SNAPSHOT=150 cards / 104 titles; cached=99; bundled=51; raw fields preserved', flush=True)

    def test_home_application_description_fields_not_identifiers(self):
        from anaconda_navigator.widgets.lists.apps import ListItemApplication
        from anaconda_navigator.widgets.lists import apps
        fake = types.SimpleNamespace(ROOT_PREFIX='C:/fixture/conda')
        self.assertGreaterEqual(len(APP_SNAPSHOT), 20)
        with mock.patch.object(apps, 'AnacondaAPI', return_value=fake):
            for row in APP_SNAPSHOT:
                with self.subTest(app=row['name'], description=row['description'][:60]):
                    item = ListItemApplication(name=row['name'], display_name=row.get('display_name') or row['name'],
                                               description=row['description'], installed=False,
                                               command='not-executed', prefix='C:/fixture/conda')
                    self.assertEqual(item.name, row['name'])
                    self.assertEqual(item.description, row['description'])
                    self.assertEqual(item.command, 'not-executed')
                    self.assertRegex(item.label_description.text(), CJK)
                    self.assertNotEqual(item.label_description.text(), row['description'])
                    item.widget.close()
        raw = CARD_SNAPSHOT[0]['title']
        self.assertEqual(QtWidgets.QLabel(raw).text(), raw)
        editor = QtWidgets.QLineEdit(); editor.setText(raw)
        combo = QtWidgets.QComboBox(); combo.addItem(raw, 'raw-id')
        self.assertEqual(editor.text(), raw)
        self.assertEqual(combo.itemText(0), raw)
        self.assertEqual(combo.itemData(0), 'raw-id')

    def test_chinese_search_uses_localized_fields_without_mutating_metadata(self):
        from anaconda_navigator.widgets.tabs.community import CommunityTab
        docs = next(row for row in CARD_SNAPSHOT if row['title'] == 'Anaconda Documentation' and row['source'] == 'cached')
        training = next(row for row in CARD_SNAPSHOT if row['title'] == 'Anaconda Certified: Data Analysis with Python in Excel')
        with mock.patch.object(CommunityTab, 'setup', lambda self: None):
            page = CommunityTab(tags=['documentation', 'training'], utm_medium='regression-test')
        page._CommunityTab__content = [docs, training]
        page._CommunityTab__make_tag_filters()
        listing = page._CommunityTab__list
        items = [native_card(row, listing) for row in (docs, training)]
        for toggle in page._CommunityTab__filter_widgets:
            toggle.setChecked(True)
        page._CommunityTab__text_filter.setText('文档')
        page._CommunityTab__filter_content()
        self.assertFalse(items[0].isHidden())
        self.assertTrue(items[1].isHidden())
        page._CommunityTab__text_filter.setText('认证')
        page._CommunityTab__filter_content()
        self.assertTrue(items[0].isHidden())
        self.assertFalse(items[1].isHidden())
        training_toggle = next(toggle for toggle in page._CommunityTab__filter_widgets
                               if toggle.objectName() == 'training')
        training_toggle.setChecked(False)
        page._CommunityTab__filter_content()
        self.assertTrue(items[1].isHidden())
        for item, row in zip(items, (docs, training)):
            self.assertEqual((item.title, item.summary, item.uri, item.tags),
                             (row['title'], row['summary'], row['uri'], row['tags']))
        page.close()

    def test_actual_category_counters_keep_english_filter_keys(self):
        from anaconda_navigator.widgets.tabs.community import CommunityTab
