    def test_real_content_badges_render_chinese_without_changing_banner(self):
        from anaconda_navigator.widgets.lists.content import ListWidgetContent
        listing = ListWidgetContent()
        seen = set()
        for row in CARD_SNAPSHOT:
            kind = nav_assets.badge_kind(row.get('banner', ''))
            if kind is None or kind in seen:
                continue
            seen.add(kind)
            item = native_card(row, listing)
            original = item.banner
            item.frame_icon.resize(260, 146)
            item.update_thumbnail()
            self.assertEqual(item.banner, original)
            self.assertEqual(item.uri, row['uri'])
            self.assertEqual(item.label_icon.accessibleName(), nav_assets.BADGE_LABELS[kind])
            pixmap = item.label_icon.pixmap()
            self.assertFalse(pixmap.isNull())
            self.assertGreater(pixmap.width(), 100)
            image = pixmap.toImage()
            colors = {image.pixelColor(x, y).rgba() for x in range(0, image.width(), 13)
                      for y in range(0, image.height(), 11)}
            self.assertGreater(len(colors), 3)
        self.assertEqual(seen, {'course', 'learning_path', 'certification'})

    def test_representative_native_cards_export_readable_png(self):
        destination = os.environ.get('ANACONDA_ZH_TEST_RENDER_DIR')
        with tempfile.TemporaryDirectory(prefix='zh-native-pages-', dir=ROOT.parent) as temporary:
            paths = render_representative_cards(destination or temporary)
            self.assertEqual(len(paths), 6)
            for path in paths:
                with self.subTest(path=path.name):
                    image = QtGui.QImage(str(path))
                    self.assertFalse(image.isNull())
                    self.assertGreaterEqual(image.width(), 200)
                    self.assertGreaterEqual(image.height(), 200)
                    self.assertGreater(path.stat().st_size, 2000)

    def test_native_dialog_context_menu_and_display_data_separation(self):
        from anaconda_navigator.widgets.manager.packages import ComboBoxPackageFilter
        from anaconda_navigator.utils import constants as C
        combo = ComboBoxPackageFilter(); combo.addItems(C.COMBOBOX_VALUES_ORDERED)
        combo.resize(200, 40); combo.show(); self.app.processEvents(); combo.grab()
        self.assertEqual(combo.currentText(), 'Installed')
        self.assertEqual(combo.property('_zhcn_display_text'), '已安装')
        self.assertEqual(C.COMBOBOX_VALUES.get(combo.currentText()), C.INSTALLED)
        self.assertEqual([combo.itemText(i) for i in range(combo.count())], C.COMBOBOX_VALUES_ORDERED)
        editor = QtWidgets.QLineEdit(); editor.setText('Home')
        menu = editor.createStandardContextMenu()
        labels = [action.text() for action in menu.actions() if not action.isSeparator()]
        self.assertTrue(any('复制' in value for value in labels), labels)
        self.assertTrue(any('粘贴' in value for value in labels), labels)
        self.assertEqual(editor.text(), 'Home')
        combo.close()

