    def test_dynamic_visible_messages_keep_substituted_names_paths_and_counts(self):
        path = r'D:\data\Home'
        cases = [
            ('Path to configuration file: ' + path, [path]),
            ('Directory path where PyCharm is installed on your machine. \n'
             'To see PyCharm on the home tab, you will also need to click \n'
             'the Refresh button on the home tab.', ['PyCharm']),
            ('<b>bad-channel</b> is not a valid conda channel.', ['bad-channel']),
            (' 2 packages will be modified 1 package will be removed 3 packages will be installed', ['2', '1', '3']),
            ('Installing application <b>Home</b> on <b>' + path + '</b>', ['Home', path]),
            ('Launching <b>Home</b>', ['Home']),
            ('<span style="font-size: 12px; font-weight: 500">No environments available for Home</span>', ['Home']),
            ('<span style="font-size: 12px; font-weight: 500">1 environment available for Home</span>', ['Home', '1']),
            ('<span style="font-size: 12px; font-weight: 500">2 environments available for Home</span>', ['Home', '2']),
        ]
        for source, preserved in cases:
            with self.subTest(source=source):
                displayed = QtWidgets.QLabel(source).text()
                self.assertNotEqual(displayed, source)
                self.assertRegex(displayed, CJK)
                for value in preserved:
                    self.assertIn(value, displayed)

    def test_native_about_and_dynamic_login_html_preserve_links(self):
        from anaconda_navigator.widgets.dialogs.about import AboutDialog
        from anaconda_navigator import __about__
        about = AboutDialog()
        shown = about.label_about.text()
        self.assertIn(__about__.__version__, shown)
        for source in ('Copyright', 'Created by Anaconda', 'For bug reports and feature requests'):
            self.assertNotIn(source, shown)
        self.assertIn('版权所有', shown)
        about.close()
        login = ('Forget your <a href="https://example.com/username?x=Home" '
                 'style="color:#43B049; text-decoration:none">username</a> or '
                 '<a href="https://example.com/password?x=on" style="color:#43B049; '
                 'text-decoration:none">password</a>? <br>'
                 '<a href="navigator://anaconda-org/login/cloud" style="color:#43B049; '
                 'text-decoration:none">Login via cloud</a>')
        displayed = QtWidgets.QLabel(login).text()
        self.assertIn('用户名', displayed)
        self.assertIn('密码', displayed)
        self.assertIn('通过云端登录', displayed)
        self.assertEqual(re.findall(r'href="([^"]+)"', displayed), re.findall(r'href="([^"]+)"', login))


